type Estrela = { nome: string; magnitude: number };
type Planeta = { nome: string; orbitaEm: number };
type Corpo = Estrela | Planeta;

// Uma função booleana normal: o in estreita cá dentro, mas o retorno é só boolean
function eEstrela(corpo: Corpo): boolean {
  return "magnitude" in corpo;
}

function descrever(corpo: Corpo): string {
  if (eEstrela(corpo)) {
    // @ts-expect-error corpo continua Estrela | Planeta: um boolean não diz ao compilador o que foi verificado
    return `magnitude ${corpo.magnitude}`;
  }
  return corpo.nome;
}

// escrito diretamente no if, o mesmo teste já estreita
function descreverInline(corpo: Corpo): string {
  if ("magnitude" in corpo) {
    return `magnitude ${corpo.magnitude}`;
  }
  return corpo.nome;
}

// em execução as duas funções fazem o mesmo; a diferença é só o que o compilador sabe
console.log(descrever({ nome: "Vega", magnitude: 0.03 }));       // "magnitude 0.03"
console.log(descreverInline({ nome: "Vega", magnitude: 0.03 })); // "magnitude 0.03"

type Estrela = { nome: string; magnitude: number };
type Planeta = { nome: string; orbitaEm: number };
type Corpo = Estrela | Planeta;

// o retorno deixa de ser boolean e passa a ser uma afirmação sobre o parâmetro
function eEstrela(corpo: Corpo): corpo is Estrela {
  return "magnitude" in corpo;
}

function descrever(corpo: Corpo): string {
  if (eEstrela(corpo)) {
    return `${corpo.nome} tem magnitude ${corpo.magnitude}`; // corpo: Estrela
  }
  return `${corpo.nome} orbita a ${corpo.orbitaEm} UA`; // corpo: Planeta
}

console.log(descrever({ nome: "Vega", magnitude: 0.03 }));  // "Vega tem magnitude 0.03"
console.log(descrever({ nome: "Marte", orbitaEm: 1.52 }));  // "Marte orbita a 1.52 UA"

// O corpo tem de devolver boolean, mas ninguém verifica se é o boolean certo:
function eEstrelaMentiroso(corpo: Corpo): corpo is Estrela {
  return true; // compila na mesma
}
console.log(eEstrelaMentiroso({ nome: "Marte", orbitaEm: 1.52 })); // true

type Leitura = { sensor: string; valor: number };

function eLeitura(dados: unknown): dados is Leitura {
  // 1. tem de ser objeto e não null, porque typeof null também dá "object"
  if (typeof dados !== "object" || dados === null) {
    return false;
  }
  // 2. as chaves têm de existir; o in estreita o próprio dados
  if (!("sensor" in dados) || !("valor" in dados)) {
    return false;
  }
  // 3. e o conteúdo tem de ter o tipo certo
  return typeof dados.sensor === "string" && typeof dados.valor === "number";
}

const bruto: unknown = JSON.parse('{"sensor":"T1","valor":21.5}');

if (eLeitura(bruto)) {
  console.log(bruto.sensor.toUpperCase()); // "T1"
  console.log(bruto.valor.toFixed(1));     // "21.5"
}

console.log(eLeitura(null));                          // false
console.log(eLeitura({ sensor: "T1" }));              // false
console.log(eLeitura({ sensor: 1, valor: "alto" }));  // false

function naoENulo(valor: string | null): boolean {
  return valor !== null;
}

function eTexto(valor: string | null): valor is string {
  return valor !== null;
}

const entradas: (string | null)[] = ["ana", null, "rui", null];

const antes = entradas.filter(naoENulo); // (string | null)[]
// @ts-expect-error o filter com predicado booleano devolve o mesmo tipo de array: antes[0] ainda pode ser null
console.log(antes[0].toUpperCase());

const depois = entradas.filter(eTexto); // string[]
console.log(depois);                              // ["ana", "rui"]
console.log(depois.map((n) => n.toUpperCase()));  // ["ANA", "RUI"]

// Com tipo: promete que, se voltar, o valor é uma string
function garantirString(valor: unknown): asserts valor is string {
  if (typeof valor !== "string") {
    throw new TypeError("Esperava uma string, recebi " + typeof valor);
  }
}

// Sem tipo: promete apenas que a condição é verdadeira
function garantir(condicao: unknown, mensagem: string): asserts condicao {
  if (!condicao) {
    throw new Error(mensagem);
  }
}

function formatarCodigo(bruto: unknown): string {
  garantirString(bruto);
  // daqui para baixo bruto é string, sem qualquer if
  garantir(bruto.length > 0, "código vazio");
  return bruto.padStart(4, "0");
}

console.log(formatarCodigo("42")); // "0042"

try {
  formatarCodigo(42);
} catch (erro) {
  console.log((erro as Error).message); // "Esperava uma string, recebi number"
}

// Uma arrow guardada numa const sem tipo escrito: declara-se, mas não pode ser usada
const garantirTexto = (valor: unknown): asserts valor is string => {
  if (typeof valor !== "string") {
    throw new TypeError("não é texto");
  }
};

function medirMal(valor: unknown): void {
  // @ts-expect-error uma assertion function só pode ser chamada por uma referência com tipo explícito
  garantirTexto(valor);
}

// A mesma arrow, agora com o tipo escrito na const: já serve
type GarantirTexto = (valor: unknown) => asserts valor is string;

const garantirTextoOk: GarantirTexto = (valor) => {
  if (typeof valor !== "string") {
    throw new TypeError("não é texto");
  }
};

function medirBem(valor: unknown): number {
  garantirTextoOk(valor);
  return valor.length;
}

console.log(medirBem("olá")); // 3

type Encomenda = { id: number; total: number };

// Predicado mentiroso: só confirma que é um objeto, mas promete uma Encomenda
function eEncomendaMentiroso(valor: unknown): valor is Encomenda {
  return typeof valor === "object" && valor !== null;
}

// Predicado alinhado: verifica exatamente as propriedades que o tipo declara
function eEncomenda(valor: unknown): valor is Encomenda {
  if (typeof valor !== "object" || valor === null) return false;
  if (!("id" in valor) || !("total" in valor)) return false;
  return typeof valor.id === "number" && typeof valor.total === "number";
}

const bruto: unknown = { id: 7 };

try {
  if (eEncomendaMentiroso(bruto)) {
    // o compilador garante um number; em execução total é undefined
    console.log(bruto.total.toFixed(2));
  }
} catch (erro) {
  console.log((erro as Error).name); // "TypeError"
}

console.log(eEncomenda(bruto)); // false

