function eNumeroFinito(valor: unknown): valor is number {
  return typeof valor === "number" && Number.isFinite(valor);
}

function formatar(valor: unknown): string {
  if (eNumeroFinito(valor)) {
    return valor.toFixed(2);
  }
  return "sem valor";
}

console.log(formatar(3.14159)); // "3.14"
console.log(formatar("3.14"));  // "sem valor"
console.log(formatar(NaN));     // "sem valor"

type Medicao = { sensor: string; celsius: number };

function eMedicao(valor: Medicao | null | undefined): valor is Medicao {
  return valor !== null && valor !== undefined;
}

const registos: (Medicao | null | undefined)[] = [
  { sensor: "T1", celsius: 21.5 },
  null,
  { sensor: "T2", celsius: 19 },
  undefined,
];

const validos = registos.filter(eMedicao); // Medicao[]
const media = validos.reduce((soma, m) => soma + m.celsius, 0) / validos.length;

console.log(validos.length);   // 2
console.log(media.toFixed(2)); // "20.25"

type Config = { host: string; porta: number };

function garantirConfig(valor: unknown): asserts valor is Config {
  if (typeof valor !== "object" || valor === null) {
    throw new TypeError("config em falta");
  }
  if (!("host" in valor) || typeof valor.host !== "string") {
    throw new TypeError("host inválido");
  }
  if (!("porta" in valor) || typeof valor.porta !== "number") {
    throw new TypeError("porta inválida");
  }
}

function arrancar(valor: unknown): string {
  garantirConfig(valor);
  return `${valor.host}:${valor.porta}`;
}

console.log(arrancar({ host: "localhost", porta: 8080 })); // "localhost:8080"

try {
  console.log(arrancar({ host: "localhost" }));
} catch (erro) {
  console.log((erro as Error).message); // "porta inválida"
}

type Fatura = { numero: string; total: number; paga: boolean };

// predicado alinhado: uma verificação por cada propriedade declarada no tipo
function eFatura(valor: unknown): valor is Fatura {
  if (typeof valor !== "object" || valor === null) return false;
  if (!("numero" in valor) || typeof valor.numero !== "string") return false;
  if (!("total" in valor) || typeof valor.total !== "number") return false;
  return "paga" in valor && typeof valor.paga === "boolean";
}

// o tipo escrito na const é o que torna a arrow chamável como assertion function
type GarantirFatura = (valor: unknown) => asserts valor is Fatura;

const garantirFatura: GarantirFatura = (valor) => {
  if (!eFatura(valor)) {
    throw new TypeError("fatura inválida");
  }
};

function recibo(valor: unknown): string {
  garantirFatura(valor);
  return `${valor.numero}: ${valor.total.toFixed(2)} ${valor.paga ? "paga" : "por pagar"}`;
}

console.log(recibo({ numero: "F1", total: 10, paga: true })); // "F1: 10.00 paga"

try {
  console.log(recibo({ numero: "F1", total: "10", paga: true }));
} catch (erro) {
  console.log((erro as Error).message); // "fatura inválida"
}
